-- Account security (one row per user): TOTP 2FA, lockout and consents.
-- totp_secret_enc is AES-256-GCM encrypted by PintoPets (key never in OpsAPI);
-- recovery_codes are SHA-256 hashes. Account Settings: /api/v2/pintopets/account-settings  (generated by `opsapi make:resource`; edit freely)
--
--   GET    /account-settings       list    ?page=&per_page=&q=&sort=&order=asc|desc&<filter>=
--   GET    /account-settings/:id   show
--   POST   /account-settings       create
--   PUT    /account-settings/:id   update (only the fields sent)
--   DELETE /account-settings/:id   delete
--
-- Every route needs a namespace (X-Namespace-Id header) and the permission
-- pintopets_account_settings.read|create|update|delete; rows are always scoped to the caller's
-- namespace. Add custom routes in this file or a new api/*.lua — see PLUGINS.md.
local sdk = require("helper.plugin-sdk")

return function(app)
    sdk.crud(app, "/account-settings", {
        table = "pintopets_account_settings",
        module = "pintopets_account_settings",
        fields = {
            user_uuid = { type = "uuid", required = true },
            totp_secret_enc = { type = "text" },
            totp_enabled_at = { type = "datetime" },
            require_code_at_sign_in = { type = "boolean" },
            recovery_codes = { type = "json" },
            failed_attempts = { type = "integer", min = 0 },
            locked_until = { type = "datetime" },
            consent_ai_learning = { type = "boolean" },
            consent_ai_learning_at = { type = "datetime" },
            consent_marketing = { type = "boolean" },
            consent_marketing_at = { type = "datetime" },
        },
        filterable = { "user_uuid", "totp_enabled_at", "require_code_at_sign_in", "failed_attempts", "locked_until", "consent_ai_learning", "consent_ai_learning_at", "consent_marketing", "consent_marketing_at" },
        sortable = { "user_uuid", "totp_enabled_at", "require_code_at_sign_in", "failed_attempts", "locked_until", "consent_ai_learning", "consent_ai_learning_at", "consent_marketing", "consent_marketing_at", "created_at", "updated_at" },
        -- Dashboard page (/dashboard/plugins/pintopets/account-settings): title, table columns, form order
        ui = {
            label = "Account security",
            columns = { "user_uuid", "totp_enabled_at", "require_code_at_sign_in", "failed_attempts", "locked_until" },
            -- Secrets (totp_secret_enc, recovery_codes) are never shown or edited here.
            form = { "user_uuid", "require_code_at_sign_in", "failed_attempts", "locked_until", "consent_ai_learning", "consent_marketing" },
        },
    })
end
